diff --git a/broker/cmd/agentos-guest-bridge/tree.go b/broker/cmd/agentos-guest-bridge/tree.go
new file mode 100644
index 000000000..b270e5f62
--- /dev/null
+++ b/broker/cmd/agentos-guest-bridge/tree.go
@@ -0,0 +1,199 @@
+package main
+
+import (
+	"bytes"
+	"context"
+	"crypto/rand"
+	"encoding/hex"
+	"encoding/json"
+	"errors"
+	"fmt"
+	"io"
+	"io/fs"
+	"log"
+	"net/http"
+	"os"
+	"path/filepath"
+	"strings"
+	"time"
+)
+
+// The managed tree's procedures, skills and context reach a live agent
+// through the broker tool managed_tree (W4), which answers only a machine
+// labelled private. syncTree keeps the tree directory a copy of it, so
+// /skills/mcp serves what the box has adopted. A failed fetch changes
+// nothing: a replay machine, whose broker serves no such tool, keeps the
+// tree it was seeded with, and a public machine keeps none.
+
+// treeNamespaces are the only directories a sync writes or removes in.
+var treeNamespaces = []string{"procedures", "skills", "context"}
+
+// maxTreeAnswer bounds a managed_tree answer as read: the broker's own
+// limit (4 MiB of files) after JSON's base64.
+const maxTreeAnswer = 8 << 20
+
+type treeAnswer struct {
+	Version   string            `json:"version"`
+	Unchanged bool              `json:"unchanged"`
+	Files     map[string][]byte `json:"files"`
+}
+
+// syncTree fetches the tree every interval until ctx ends.
+func syncTree(ctx context.Context, broker *http.Client, dir string, every time.Duration) {
+	version, last := "", ""
+	for {
+		v, err := syncOnce(ctx, broker, dir, version)
+		switch {
+		case err != nil && err.Error() != last:
+			last = err.Error()
+			log.Printf("managed tree: %v", err)
+		case err == nil:
+			version, last = v, ""
+		}
+		t := time.NewTimer(every)
+		select {
+		case <-ctx.Done():
+			t.Stop()
+			return
+		case <-t.C:
+		}
+	}
+}
+
+// syncOnce fetches the tree unless it is still version, and writes it.
+// It returns the version now held.
+func syncOnce(ctx context.Context, broker *http.Client, dir, version string) (string, error) {
+	args, _ := json.Marshal(map[string]string{"version": version})
+	body, _ := json.Marshal(map[string]any{
+		"jsonrpc": "2.0", "id": 1, "method": "tools/call",
+		"params": map[string]any{"name": "managed_tree", "arguments": json.RawMessage(args)},
+	})
+	ctx, cancel := context.WithTimeout(ctx, time.Minute)
+	defer cancel()
+	req, err := http.NewRequestWithContext(ctx, http.MethodPost, "http://broker.localhost/mcp", bytes.NewReader(body))
+	if err != nil {
+		return version, err
+	}
+	req.Header.Set("Content-Type", "application/json")
+	resp, err := broker.Do(req)
+	if err != nil {
+		return version, err
+	}
+	defer resp.Body.Close()
+	var out struct {
+		Result *struct {
+			Content []struct {
+				Text string `json:"text"`
+			} `json:"content"`
+			IsError bool `json:"isError"`
+		} `json:"result"`
+		Error *struct {
+			Message string `json:"message"`
+		} `json:"error"`
+	}
+	if err := json.NewDecoder(io.LimitReader(resp.Body, maxTreeAnswer)).Decode(&out); err != nil {
+		return version, fmt.Errorf("broker answer: %v", err)
+	}
+	switch {
+	case out.Error != nil:
+		return version, errors.New(out.Error.Message)
+	case out.Result == nil || len(out.Result.Content) == 0:
+		return version, errors.New("empty broker answer")
+	case out.Result.IsError:
+		return version, errors.New(out.Result.Content[0].Text)
+	}
+	var ans treeAnswer
+	if err := json.Unmarshal([]byte(out.Result.Content[0].Text), &ans); err != nil {
+		return version, fmt.Errorf("broker answer: %v", err)
+	}
+	if ans.Unchanged {
+		if ans.Version != version {
+			// Not ours: an unchanged answer never wipes the tree.
+			return version, errors.New("broker answer: unchanged, but not the version held")
+		}
+		return version, nil
+	}
+	if err := mirror(dir, ans.Files); err != nil {
+		return version, err
+	}
+	return ans.Version, nil
+}
+
+// mirror makes dir's tree namespaces hold exactly files. Every path is
+// checked before anything is written, so a bad answer changes nothing.
+// New and changed files are written first, each written aside and
+// renamed, so the skill server never reads half of one; files gone from
+// the tree are removed last, so a failed write leaves the old tree's
+// files rather than fewer. Everything goes through an os.Root, so a
+// symlink in dir cannot send a write outside it.
+func mirror(dir string, files map[string][]byte) error {
+	for p := range files {
+		ns, _, _ := strings.Cut(p, "/")
+		if !filepath.IsLocal(p) || filepath.Clean(p) != p || !inTree(ns) || ns == p {
+			return fmt.Errorf("bad tree path %q", p)
+		}
+	}
+	if err := os.MkdirAll(dir, 0o755); err != nil {
+		return err
+	}
+	root, err := os.OpenRoot(dir)
+	if err != nil {
+		return err
+	}
+	defer root.Close()
+	for p, b := range files {
+		if old, err := root.ReadFile(p); err == nil && bytes.Equal(old, b) {
+			continue
+		}
+		if err := root.MkdirAll(filepath.Dir(p), 0o755); err != nil {
+			return err
+		}
+		var n [8]byte
+		rand.Read(n[:])
+		tmp := filepath.Join(filepath.Dir(p), ".tree-"+hex.EncodeToString(n[:]))
+		f, err := root.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
+		if err != nil {
+			return err
+		}
+		_, err = f.Write(b)
+		if cerr := f.Close(); err == nil {
+			err = cerr
+		}
+		if err == nil {
+			err = root.Chmod(tmp, 0o644)
+		}
+		if err == nil {
+			err = root.Rename(tmp, p)
+		}
+		if err != nil {
+			root.Remove(tmp)
+			return err
+		}
+	}
+	for _, ns := range treeNamespaces {
+		var gone []string
+		fs.WalkDir(root.FS(), ns, func(path string, d fs.DirEntry, err error) error {
+			if err == nil && !d.IsDir() {
+				if _, keep := files[path]; !keep {
+					gone = append(gone, path)
+				}
+			}
+			return nil
+		})
+		for _, p := range gone {
+			if err := root.Remove(p); err != nil {
+				return err
+			}
+		}
+	}
+	return nil
+}
+
+func inTree(ns string) bool {
+	for _, n := range treeNamespaces {
+		if n == ns {
+			return true
+		}
+	}
+	return false
+}
diff --git a/broker/cmd/agentos-guest-bridge/tree_test.go b/broker/cmd/agentos-guest-bridge/tree_test.go
new file mode 100644
index 000000000..3d6b95b1b
--- /dev/null
+++ b/broker/cmd/agentos-guest-bridge/tree_test.go
@@ -0,0 +1,159 @@
+package main
+
+// REQ: CAP-5, REV-5
+
+import (
+	"context"
+	"encoding/json"
+	"net"
+	"net/http"
+	"os"
+	"path/filepath"
+	"sync"
+	"testing"
+)
+
+// fakeTree is a broker socket whose /mcp answers managed_tree.
+type fakeTree struct {
+	mu    sync.Mutex
+	ans   treeAnswer
+	err   string // a tool error, as for a public machine
+	rpc   bool   // a JSON-RPC error, as a broker with no such tool gives
+	asked []string
+}
+
+func (f *fakeTree) serve(t *testing.T) *http.Client {
+	t.Helper()
+	sock := filepath.Join(t.TempDir(), "b.sock")
+	l, err := net.Listen("unix", sock)
+	if err != nil {
+		t.Fatal(err)
+	}
+	srv := &http.Server{Handler: http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+		var req struct {
+			Params struct {
+				Name      string          `json:"name"`
+				Arguments json.RawMessage `json:"arguments"`
+			} `json:"params"`
+		}
+		json.NewDecoder(r.Body).Decode(&req)
+		var a struct{ Version string }
+		json.Unmarshal(req.Params.Arguments, &a)
+		f.mu.Lock()
+		defer f.mu.Unlock()
+		f.asked = append(f.asked, a.Version)
+		switch {
+		case f.rpc || req.Params.Name != "managed_tree":
+			json.NewEncoder(w).Encode(map[string]any{"error": map[string]any{"message": "no such tool"}})
+		case f.err != "":
+			json.NewEncoder(w).Encode(map[string]any{"result": map[string]any{"isError": true, "content": []any{map[string]any{"text": f.err}}}})
+		default:
+			ans := f.ans
+			if a.Version == ans.Version {
+				ans = treeAnswer{Version: ans.Version, Unchanged: true}
+			}
+			b, _ := json.Marshal(ans)
+			json.NewEncoder(w).Encode(map[string]any{"result": map[string]any{"content": []any{map[string]any{"text": string(b)}}}})
+		}
+	})}
+	go srv.Serve(l)
+	t.Cleanup(func() { srv.Close() })
+	return &http.Client{Transport: &http.Transport{DialContext: func(ctx context.Context, _, _ string) (net.Conn, error) {
+		return (&net.Dialer{}).DialContext(ctx, "unix", sock)
+	}}}
+}
+
+func read(t *testing.T, path string) string {
+	t.Helper()
+	b, err := os.ReadFile(path)
+	if err != nil {
+		return "<none>"
+	}
+	return string(b)
+}
+
+// W4: the bridge keeps its tree directory a copy of the broker's tree:
+// new files written, gone ones removed, nothing outside the tree's
+// namespaces touched; an unchanged version writes nothing.
+func TestBridgeMirrorsTheManagedTree(t *testing.T) {
+	dir := t.TempDir()
+	os.MkdirAll(filepath.Join(dir, "skills"), 0o755)
+	os.WriteFile(filepath.Join(dir, "skills", "old.json"), []byte("old"), 0o644)
+	os.WriteFile(filepath.Join(dir, "notes.txt"), []byte("mine"), 0o644)
+	f := &fakeTree{ans: treeAnswer{Version: "v1", Files: map[string][]byte{
+		"skills/greet.json": []byte("greet"), "procedures/p.json": []byte("p"), "context/a/b.md": []byte("b")}}}
+	c := f.serve(t)
+	v, err := syncOnce(context.Background(), c, dir, "")
+	if err != nil || v != "v1" {
+		t.Fatalf("sync: %q %v", v, err)
+	}
+	for p, want := range map[string]string{"skills/greet.json": "greet", "procedures/p.json": "p", "context/a/b.md": "b",
+		"skills/old.json": "<none>", "notes.txt": "mine"} {
+		if got := read(t, filepath.Join(dir, p)); got != want {
+			t.Errorf("%s = %q, want %q", p, got, want)
+		}
+	}
+	if fi, _ := os.Stat(filepath.Join(dir, "skills/greet.json")); fi.Mode().Perm() != 0o644 {
+		t.Errorf("mode %v", fi.Mode().Perm())
+	}
+	os.WriteFile(filepath.Join(dir, "skills", "greet.json"), []byte("edited"), 0o644)
+	if v, err := syncOnce(context.Background(), c, dir, v); err != nil || v != "v1" || read(t, filepath.Join(dir, "skills/greet.json")) != "edited" {
+		t.Fatalf("unchanged version rewrote the tree: %q %v", v, err)
+	}
+	f.mu.Lock()
+	f.ans = treeAnswer{Version: "v2", Files: map[string][]byte{"skills/greet.json": []byte("greet2")}}
+	f.mu.Unlock()
+	if v, err := syncOnce(context.Background(), c, dir, v); err != nil || v != "v2" {
+		t.Fatalf("v2: %q %v", v, err)
+	}
+	if read(t, filepath.Join(dir, "skills/greet.json")) != "greet2" || read(t, filepath.Join(dir, "procedures/p.json")) != "<none>" {
+		t.Fatal("v2 not mirrored")
+	}
+}
+
+// A refusal (a public machine), a broker with no managed_tree (a replay
+// machine, whose seed is the tree under test), or an answer with a path
+// outside the tree's namespaces changes nothing.
+func TestBridgeKeepsItsTreeWhenTheBrokerDoesNotSendOne(t *testing.T) {
+	for name, f := range map[string]*fakeTree{
+		"public":    {err: "the managed tree reaches only private machines"},
+		"replay":    {rpc: true},
+		"escape":    {ans: treeAnswer{Version: "v1", Files: map[string][]byte{"skills/a.json": []byte("a"), "../../etc/passwd": []byte("x")}}},
+		"grants":    {ans: treeAnswer{Version: "v1", Files: map[string][]byte{"grants/g.json": []byte("g")}}},
+		"dotdot":    {ans: treeAnswer{Version: "v1", Files: map[string][]byte{"skills/../../x": []byte("x")}}},
+		"absolute":  {ans: treeAnswer{Version: "v1", Files: map[string][]byte{"/skills/x.json": []byte("x")}}},
+		"oversize":  {ans: treeAnswer{Version: "v1", Files: map[string][]byte{"skills/big.json": make([]byte, maxTreeAnswer)}}},
+		"unchanged": {ans: treeAnswer{Version: "v9", Unchanged: true}},
+		"not ready": {err: "the managed tree is not ready; keep the one you have"},
+	} {
+		t.Run(name, func(t *testing.T) {
+			dir := t.TempDir()
+			os.MkdirAll(filepath.Join(dir, "skills"), 0o755)
+			os.WriteFile(filepath.Join(dir, "skills", "seeded.json"), []byte("seed"), 0o644)
+			v, err := syncOnce(context.Background(), f.serve(t), dir, "")
+			if err == nil || v != "" {
+				t.Fatalf("sync: %q %v", v, err)
+			}
+			if read(t, filepath.Join(dir, "skills/seeded.json")) != "seed" || read(t, filepath.Join(dir, "skills/a.json")) != "<none>" {
+				t.Fatal("the tree changed")
+			}
+		})
+	}
+}
+
+// L3 on #120: a symlink in the tree directory cannot send a write, or a
+// removal, outside it.
+func TestBridgeMirrorStaysInsideTheTree(t *testing.T) {
+	dir, outside := t.TempDir(), t.TempDir()
+	os.WriteFile(filepath.Join(outside, "keep.json"), []byte("outside"), 0o644)
+	if err := os.Symlink(outside, filepath.Join(dir, "skills")); err != nil {
+		t.Fatal(err)
+	}
+	f := &fakeTree{ans: treeAnswer{Version: "v1", Files: map[string][]byte{"skills/a.json": []byte("a")}}}
+	if _, err := syncOnce(context.Background(), f.serve(t), dir, ""); err == nil {
+		t.Fatal("wrote through a symlink")
+	}
+	if read(t, filepath.Join(outside, "a.json")) != "<none>" || read(t, filepath.Join(outside, "keep.json")) != "outside" {
+		t.Fatal("the mirror reached outside the tree")
+	}
+}
