diff --git a/broker/cmd/agentosd/tree.go b/broker/cmd/agentosd/tree.go
new file mode 100644
index 000000000..5d9933daf
--- /dev/null
+++ b/broker/cmd/agentosd/tree.go
@@ -0,0 +1,208 @@
+package main
+
+import (
+	"context"
+	"encoding/json"
+	"errors"
+	"fmt"
+	"strings"
+	"sync"
+
+	"github.com/ghbmrk/agentos/broker/change"
+	"github.com/ghbmrk/agentos/broker/guest"
+	"github.com/ghbmrk/agentos/broker/vm"
+)
+
+// agentNamespaces are the managed tree's namespaces a guest reads (replay
+// R5): what Loop 1 adopts for the agent, and nothing with authority.
+var agentNamespaces = []string{"procedures", "skills", "context"}
+
+// toolTree is the broker tool through which a guest fetches the live
+// managed tree (W4). It is a broker tool over MCP (ARC-6 (b)), not a new
+// service.
+const toolTree = "managed_tree"
+
+// maxTreeSend bounds one managed_tree answer. A tree past it is not sent
+// at all, so a guest never runs half of one.
+const maxTreeSend = 4 << 20
+
+// liveTree is the live agent's copy of the managed tree (W4): the change
+// pipeline's target for agentNamespaces, so an adoption, an UNDO or a
+// restart's restore lands here, and the guest's bridge fetches it with
+// managed_tree. The tree is derived from owner tasks and no file carries a
+// public mark yet, so only a machine already labelled private gets it
+// (REV-5, compile K7); a public machine is refused and never raised, so a
+// PUBLIC task stays public. Memory only: the pipeline holds the state and
+// applies it again at start.
+type liveTree struct {
+	mu    sync.Mutex
+	files change.Tree
+	// version is files' hash, kept by Apply. ready is set once the
+	// pipeline has opened and applied its state: until then the copy is
+	// empty but not the box's tree, and a guest mirroring it would delete
+	// every skill it holds (L3 on #120).
+	version string
+	ready   bool
+	// label reports a machine's label; nil (no machine plane) refuses
+	// every machine.
+	label func(machine string) (vm.Label, error)
+	logf  func(format string, args ...any)
+}
+
+func newLiveTree(logf func(string, ...any)) *liveTree {
+	return &liveTree{files: change.Tree{}, version: change.Tree{}.Hash(), logf: logf}
+}
+
+// markReady is called once the pipeline has opened with its targets
+// applied; before it, and with no learning plane at all, managed_tree
+// answers "not ready" and a guest keeps the tree it has.
+func (t *liveTree) markReady() {
+	t.mu.Lock()
+	defer t.mu.Unlock()
+	t.ready = true
+}
+
+// targets are the pipeline's targets for agentNamespaces.
+func (t *liveTree) targets() map[string]change.Target {
+	out := map[string]change.Target{}
+	for _, ns := range agentNamespaces {
+		out[ns] = treeTarget{t, ns}
+	}
+	return out
+}
+
+type treeTarget struct {
+	t  *liveTree
+	ns string
+}
+
+// Current is empty: the pipeline's own state is the record, applied at
+// start (change C1).
+func (g treeTarget) Current() (change.Tree, error) { return change.Tree{}, nil }
+
+func (g treeTarget) Apply(files change.Tree) error {
+	for p := range files {
+		if ns, _, _ := strings.Cut(p, "/"); ns != g.ns {
+			return fmt.Errorf("managed tree: %s is outside %s", p, g.ns)
+		}
+	}
+	g.t.mu.Lock()
+	defer g.t.mu.Unlock()
+	for p := range g.t.files {
+		if ns, _, _ := strings.Cut(p, "/"); ns == g.ns {
+			delete(g.t.files, p)
+		}
+	}
+	for p, b := range files {
+		g.t.files[p] = append([]byte(nil), b...)
+	}
+	g.t.version = g.t.files.Hash()
+	return nil
+}
+
+// treeAnswer is managed_tree's result. Version is the tree's hash; a
+// caller that already holds it gets Unchanged and no files.
+type treeAnswer struct {
+	Version   string            `json:"version"`
+	Unchanged bool              `json:"unchanged,omitempty"`
+	Files     map[string][]byte `json:"files,omitempty"`
+}
+
+var (
+	errTreePublic   = errors.New("the managed tree reaches only private machines; this one has had no owner data")
+	errTreeNotReady = errors.New("the managed tree is not ready; keep the one you have")
+)
+
+func (t *liveTree) List() []map[string]any {
+	return []map[string]any{{
+		"name": toolTree,
+		"description": "Fetch the box's adopted procedures, skills and context (the managed tree). " +
+			"Pass the version you hold to learn whether it changed. Only a machine that has had owner data gets it.",
+		"inputSchema": map[string]any{
+			"type":       "object",
+			"properties": map[string]any{"version": map[string]any{"type": "string"}},
+		},
+	}}
+}
+
+func (t *liveTree) Call(_ context.Context, machine, _, name string, args json.RawMessage) (string, bool, error) {
+	if name != toolTree {
+		return "", false, nil
+	}
+	var a struct {
+		Version string `json:"version"`
+	}
+	if len(args) > 0 {
+		if err := json.Unmarshal(args, &a); err != nil {
+			return "", true, errors.New("arguments must be an object")
+		}
+	}
+	t.mu.Lock()
+	label := t.label
+	t.mu.Unlock()
+	if label == nil {
+		return "", true, errTreePublic
+	}
+	// The label is read before the tree, so a tree read here was owed to
+	// a machine that was private when it asked.
+	if l, err := label(machine); err != nil || l != vm.Private {
+		return "", true, errTreePublic
+	}
+	t.mu.Lock()
+	if !t.ready {
+		t.mu.Unlock()
+		return "", true, errTreeNotReady
+	}
+	files := change.Tree{}
+	size := 0
+	for p, b := range t.files {
+		files[p] = b
+		size += len(p) + len(b)
+	}
+	ans := treeAnswer{Version: t.version}
+	t.mu.Unlock()
+	if ans.Version == a.Version {
+		ans.Unchanged = true
+	} else if size > maxTreeSend {
+		t.logf("managed tree not sent to %s: %d bytes, over %d", machine, size, maxTreeSend)
+		return "", true, errors.New("the managed tree is too large to send")
+	} else {
+		ans.Files = files
+	}
+	b, err := json.Marshal(ans)
+	return string(b), true, err
+}
+
+// setMachines lets managed_tree read machine labels once the machine
+// plane is open.
+func (t *liveTree) setMachines(m *vm.Manager) {
+	t.mu.Lock()
+	defer t.mu.Unlock()
+	t.label = m.Label
+}
+
+// toolSet serves several broker tool sets on one guest socket (guest
+// G15), in order; a nil entry is skipped.
+type toolSet []guest.Tools
+
+func (s toolSet) List() []map[string]any {
+	var out []map[string]any
+	for _, t := range s {
+		if t != nil {
+			out = append(out, t.List()...)
+		}
+	}
+	return out
+}
+
+func (s toolSet) Call(ctx context.Context, machine, lineage, name string, args json.RawMessage) (string, bool, error) {
+	for _, t := range s {
+		if t == nil {
+			continue
+		}
+		if text, ok, err := t.Call(ctx, machine, lineage, name, args); ok {
+			return text, ok, err
+		}
+	}
+	return "", false, nil
+}
diff --git a/broker/cmd/agentosd/tree_test.go b/broker/cmd/agentosd/tree_test.go
new file mode 100644
index 000000000..63039543d
--- /dev/null
+++ b/broker/cmd/agentosd/tree_test.go
@@ -0,0 +1,197 @@
+package main
+
+import (
+	"context"
+	"encoding/json"
+	"errors"
+	"os"
+	"path/filepath"
+	"strings"
+	"testing"
+
+	"github.com/ghbmrk/agentos/broker/admission"
+	"github.com/ghbmrk/agentos/broker/change"
+	"github.com/ghbmrk/agentos/broker/daemon"
+	"github.com/ghbmrk/agentos/broker/vm"
+)
+
+// REQ: CAP-5, REV-5, ARC-6
+
+type noEval struct{}
+
+func (noEval) Run(context.Context, change.Tree, change.Probe) ([]byte, error) {
+	return nil, change.ErrNotEvaluated
+}
+
+func labels(m map[string]vm.Label) func(string) (vm.Label, error) {
+	return func(id string) (vm.Label, error) {
+		l, ok := m[id]
+		if !ok {
+			return 0, vm.ErrUnknown
+		}
+		return l, nil
+	}
+}
+
+func fetchTree(t *testing.T, lt *liveTree, machine, version string) (treeAnswer, error) {
+	t.Helper()
+	args, _ := json.Marshal(map[string]string{"version": version})
+	text, ok, err := lt.Call(context.Background(), machine, "lin", toolTree, args)
+	if !ok {
+		t.Fatal("managed_tree not handled")
+	}
+	if err != nil {
+		return treeAnswer{}, err
+	}
+	var a treeAnswer
+	if err := json.Unmarshal([]byte(text), &a); err != nil {
+		t.Fatal(err)
+	}
+	return a, nil
+}
+
+// W4: the pipeline's procedures, skills and context reach the live agent
+// through managed_tree. agentosd wires the tree as the pipeline's target
+// for those namespaces, so the adopted tree is applied to it at start, as
+// after every adoption and UNDO; nothing with authority is sent.
+func TestW4AdoptedTreeReachesTheAgent(t *testing.T) {
+	dir := t.TempDir()
+	skillFile := []byte(`{"id":"greet"}`)
+	// An earlier run adopted a skill and a grant change.
+	if _, err := change.New(change.Config{
+		Store:     change.FileStore{Path: filepath.Join(dir, "change.json")},
+		Evaluator: noEval{},
+		Initial: change.Tree{"skills/greet.json": skillFile, "procedures/p.json": []byte("p"),
+			"context/c.md": []byte("c"), "grants/g.json": []byte("g")},
+	}); err != nil {
+		t.Fatal(err)
+	}
+	cfg := daemon.Config{
+		JournalPath: filepath.Join(dir, "journal.log"), SocketDir: filepath.Join(dir, "run"),
+		OwnerNumber: ownerNum, ModemUID: os.Getuid(), Admission: admission.Config{CapacityMB: 4500, HeadroomMB: 600},
+		OwnerState: filepath.Join(dir, "owner.json"),
+	}
+	lt := newLiveTree(t.Logf)
+	if _, err := openLearning(learnPaths{Dir: dir, Spare: filepath.Join(dir, "spare.json"), Tree: lt}, false, &cfg); err != nil {
+		t.Fatal(err)
+	}
+	lt.label = labels(map[string]vm.Label{"agent": vm.Private})
+	a, err := fetchTree(t, lt, "agent", "")
+	if err != nil {
+		t.Fatal(err)
+	}
+	if len(a.Files) != 3 || string(a.Files["skills/greet.json"]) != string(skillFile) || a.Files["grants/g.json"] != nil {
+		t.Fatalf("tree sent: %v", a.Files)
+	}
+	// The version is the tree's: asking with it sends nothing.
+	again, err := fetchTree(t, lt, "agent", a.Version)
+	if err != nil || !again.Unchanged || again.Files != nil {
+		t.Fatalf("unchanged tree: %+v %v", again, err)
+	}
+	// An UNDO applies the namespace without the file.
+	if err := (treeTarget{lt, "skills"}).Apply(change.Tree{}); err != nil {
+		t.Fatal(err)
+	}
+	after, _ := fetchTree(t, lt, "agent", a.Version)
+	if after.Unchanged || len(after.Files) != 2 || after.Files["skills/greet.json"] != nil {
+		t.Fatalf("after undo: %+v", after)
+	}
+}
+
+// REV-5, compile K7: the tree is derived from owner tasks, so only a
+// machine already labelled private gets it. A public machine is refused
+// and not raised, an unknown one too, and so is every machine before the
+// machine plane opens.
+func TestW4TreeReachesOnlyPrivateMachines(t *testing.T) {
+	lt := newLiveTree(t.Logf)
+	lt.markReady()
+	treeTarget{lt, "skills"}.Apply(change.Tree{"skills/a.json": []byte("a")})
+	if _, err := fetchTree(t, lt, "agent", ""); !errors.Is(err, errTreePublic) {
+		t.Fatalf("before the machine plane: %v", err)
+	}
+	ls := map[string]vm.Label{"agent": vm.Public, "fork": vm.Private}
+	lt.label = labels(ls)
+	for _, m := range []string{"agent", "nobody"} {
+		if _, err := fetchTree(t, lt, m, ""); !errors.Is(err, errTreePublic) {
+			t.Fatalf("%s: %v", m, err)
+		}
+	}
+	if ls["agent"] != vm.Public {
+		t.Fatal("a public machine was raised")
+	}
+	if a, err := fetchTree(t, lt, "fork", ""); err != nil || len(a.Files) != 1 {
+		t.Fatalf("private machine: %+v %v", a, err)
+	}
+}
+
+// A tree past maxTreeSend is not sent in part.
+func TestW4OversizeTreeIsNotSent(t *testing.T) {
+	lt := newLiveTree(t.Logf)
+	lt.label = labels(map[string]vm.Label{"agent": vm.Private})
+	lt.markReady()
+	treeTarget{lt, "context"}.Apply(change.Tree{"context/big.md": make([]byte, maxTreeSend)})
+	if _, err := fetchTree(t, lt, "agent", ""); err == nil || !strings.Contains(err.Error(), "too large") {
+		t.Fatalf("oversize: %v", err)
+	}
+}
+
+// G15: the guest socket lists the question tools and managed_tree, and
+// each name goes to its own set.
+func TestToolSetServesEachSet(t *testing.T) {
+	lt := newLiveTree(t.Logf)
+	lt.label = labels(map[string]vm.Label{"agent": vm.Private})
+	lt.markReady()
+	q := &questions{}
+	set := toolSet{nil, q, lt}
+	names := map[string]bool{}
+	for _, tl := range set.List() {
+		names[tl["name"].(string)] = true
+	}
+	if !names[toolTree] || !names["owner_question"] {
+		t.Fatalf("listed %v", names)
+	}
+	if _, ok, err := set.Call(context.Background(), "agent", "lin", toolTree, nil); !ok || err != nil {
+		t.Fatalf("managed_tree: %v %v", ok, err)
+	}
+	if _, ok, err := set.Call(context.Background(), "agent", "lin", "owner_question", nil); !ok || err == nil {
+		t.Fatalf("question tool with no book: %v %v", ok, err)
+	}
+	if _, ok, _ := set.Call(context.Background(), "agent", "lin", "effect_request", nil); ok {
+		t.Fatal("handled a tool no set serves")
+	}
+}
+
+// L3 on #120: before the pipeline has opened and applied its state, and
+// with no learning plane at all, the copy is empty but is not the box's
+// tree, so it is not sent: a guest mirroring it would delete every skill
+// it holds.
+func TestW4TreeIsNotSentUntilThePipelineOpens(t *testing.T) {
+	lt := newLiveTree(t.Logf)
+	lt.label = labels(map[string]vm.Label{"agent": vm.Private})
+	if _, err := fetchTree(t, lt, "agent", ""); !errors.Is(err, errTreeNotReady) {
+		t.Fatalf("before the pipeline: %v", err)
+	}
+	dir := t.TempDir()
+	cfg := daemon.Config{
+		JournalPath: filepath.Join(dir, "journal.log"), SocketDir: filepath.Join(dir, "run"),
+		OwnerNumber: ownerNum, ModemUID: os.Getuid(), Admission: admission.Config{CapacityMB: 4500, HeadroomMB: 600},
+		OwnerState: filepath.Join(dir, "owner.json"),
+	}
+	if _, err := openLearning(learnPaths{Dir: dir, Spare: filepath.Join(dir, "spare.json"), Tree: lt}, false, &cfg); err != nil {
+		t.Fatal(err)
+	}
+	if a, err := fetchTree(t, lt, "agent", ""); err != nil || len(a.Files) != 0 || a.Version == "" {
+		t.Fatalf("a first start's empty tree: %+v %v", a, err)
+	}
+}
+
+// A target applies only its own namespace.
+func TestW4TargetRefusesOtherNamespaces(t *testing.T) {
+	lt := newLiveTree(t.Logf)
+	if err := (treeTarget{lt, "skills"}).Apply(change.Tree{"skills/a.json": nil, "grants/g.json": []byte("g")}); err == nil {
+		t.Fatal("a skills target applied a grants file")
+	}
+	if len(lt.files) != 0 {
+		t.Fatalf("partly applied: %v", lt.files)
+	}
+}
